-- C2: CPMK untuk SI301 - Introduction to Linguistics
INSERT INTO cpmk (id, course_id, code, description) VALUES
('17000000-0000-0000-0000-000000000001', '10000000-0000-0000-0003-000000000001', 'CPMK-01', 'Mahasiswa mampu menjelaskan konsep dasar linguistik dan cabang-cabang ilmu linguistik.'),
('17000000-0000-0000-0000-000000000002', '10000000-0000-0000-0003-000000000001', 'CPMK-02', 'Mahasiswa mampu menganalisis sistem bunyi bahasa Inggris (fonetik dan fonologi dasar).'),
('17000000-0000-0000-0000-000000000003', '10000000-0000-0000-0003-000000000001', 'CPMK-03', 'Mahasiswa mampu mengidentifikasi dan menganalisis struktur kata (morfologi dasar) bahasa Inggris.'),
('17000000-0000-0000-0000-000000000004', '10000000-0000-0000-0003-000000000001', 'CPMK-04', 'Mahasiswa mampu menganalisis struktur kalimat (sintaksis dasar) bahasa Inggris menggunakan diagram pohon.'),
('17000000-0000-0000-0000-000000000005', '10000000-0000-0000-0003-000000000001', 'CPMK-05', 'Mahasiswa mampu menjelaskan konsep makna (semantik) dan penggunaan bahasa dalam konteks (pragmatik).'),
-- CPMK untuk SI307 - Translation Theory
('17000000-0000-0000-0000-000000000006', '10000000-0000-0000-0003-000000000007', 'CPMK-01', 'Mahasiswa mampu menjelaskan sejarah dan perkembangan teori penerjemahan.'),
('17000000-0000-0000-0000-000000000007', '10000000-0000-0000-0003-000000000007', 'CPMK-02', 'Mahasiswa mampu membedakan berbagai pendekatan penerjemahan (domesticating vs foreignizing, equivalence, dll).'),
('17000000-0000-0000-0000-000000000008', '10000000-0000-0000-0003-000000000007', 'CPMK-03', 'Mahasiswa mampu menerapkan teknik penerjemahan pada berbagai jenis teks.');

-- C3: Sub-CPMK untuk SI301
INSERT INTO sub_cpmk (id, cpmk_id, code, description) VALUES
('18000000-0000-0000-0000-000000000001', '17000000-0000-0000-0000-000000000001', 'Sub-01.1', 'Mampu mendefinisikan linguistik dan membedakan linguistik deskriptif vs preskriptif.'),
('18000000-0000-0000-0000-000000000002', '17000000-0000-0000-0000-000000000001', 'Sub-01.2', 'Mampu menjelaskan cabang linguistik: fonologi, morfologi, sintaksis, semantik, pragmatik.'),
('18000000-0000-0000-0000-000000000003', '17000000-0000-0000-0000-000000000002', 'Sub-02.1', 'Mampu mengidentifikasi dan mentranskripsi bunyi bahasa Inggris menggunakan IPA.'),
('18000000-0000-0000-0000-000000000004', '17000000-0000-0000-0000-000000000002', 'Sub-02.2', 'Mampu menjelaskan konsep fonem, alofon, dan minimal pair.'),
('18000000-0000-0000-0000-000000000005', '17000000-0000-0000-0000-000000000003', 'Sub-03.1', 'Mampu mengidentifikasi morfem bebas dan terikat.'),
('18000000-0000-0000-0000-000000000006', '17000000-0000-0000-0000-000000000003', 'Sub-03.2', 'Mampu menganalisis proses pembentukan kata (derivation, inflection, compounding).'),
('18000000-0000-0000-0000-000000000007', '17000000-0000-0000-0000-000000000004', 'Sub-04.1', 'Mampu menggambarkan struktur kalimat menggunakan tree diagram.'),
('18000000-0000-0000-0000-000000000008', '17000000-0000-0000-0000-000000000004', 'Sub-04.2', 'Mampu mengidentifikasi konstituen dan relasi gramatikal.'),
('18000000-0000-0000-0000-000000000009', '17000000-0000-0000-0000-000000000005', 'Sub-05.1', 'Mampu menganalisis makna leksikal, hubungan makna (sinonim, antonim, homonim, polisemi).'),
('18000000-0000-0000-0000-000000000010', '17000000-0000-0000-0000-000000000005', 'Sub-05.2', 'Mampu menjelaskan tindak tutur (speech acts) dan prinsip kerjasama Grice.');

